{"script":"async () => {
  // Wait for the Cloudflare verification to complete
  for (let i = 0; i < 30; i++) {
    await new Promise(r => setTimeout(r, 1000));
    if (!document.title.includes('验证') && !document.body.innerText.includes('安全验证')) {
      return {status: 'passed', waited: i+1, url: window.location.href, title: document.title};
    }
  }
  return {status: 'still_blocked', url: window.location.href, title: document.title};
}"}

